{
  "mechanism_id": "behavior_conditioned_codebook_directional_transport",
  "version": "3.0.0",
  "title": "Behaviour-conditioned codebook directional transport",
  "equation": "For each valid pair b, let p_s[b,j] = softmax_j(-||source[b]-codebook[j]||^2 / tau), p_t[b,j] = softmax_j(-||target[b]-codebook[j]||^2 / tau), q_s[b] = sum_j p_s[b,j] codebook[j], q_t[b] = sum_j p_t[b,j] codebook[j], and y[b] = target[b]-source[b]. Define L = sum_b mask[b] * (|| (q_t[b]-q_s[b])-y[b] ||_2^2 + alpha * (1 - dot(q_s[b], y[b]) / (||q_s[b]||_2 * ||y[b]||_2 + epsilon))) / (sum_b mask[b] + epsilon).",
  "symbols": {
    "B": "Number of source-target pairs in the batch.",
    "D": "Embedding dimension.",
    "C": "Number of codebook rows.",
    "source[b]": "Source item residual or representation for pair b.",
    "target[b]": "Behaviour-linked target item residual or representation for pair b.",
    "codebook[j]": "Trainable row j of the codebook used by the affected quantization level.",
    "p_s[b,j]": "Soft assignment probability of source b to codebook row j.",
    "p_t[b,j]": "Soft assignment probability of target b to codebook row j.",
    "q_s[b]": "Soft codebook representation of the source.",
    "q_t[b]": "Soft codebook representation of the target.",
    "y[b]": "Observed directed behaviour displacement, target minus source.",
    "mask[b]": "Binary validity indicator for pair b.",
    "tau": "Soft-assignment temperature.",
    "alpha": "Weight of the directed source-alignment component within the mechanism.",
    "epsilon": "Positive numerical-stability constant.",
    "L": "Masked mean mechanism loss."
  },
  "parameters": {
    "tau": 0.5,
    "alpha": 0.1,
    "epsilon": 1e-8
  },
  "target_paths": [
    "encoder",
    "codebook",
    "hard_sid_export"
  ],
  "hypotheses": [
    "The transport residual term makes source and target representations jointly organize around codebook rows so that their codebook displacement tracks observed directed behaviour displacement.",
    "The directed source-alignment component distinguishes source from target and adds a behaviour-sensitive signal without using a detached metric.",
    "Selection criterion: retain the mechanism only if matched downstream Stage-3 recall@10 improves over control and the improvement is reproducible across seeds, with no collapse signature in code usage; Hard-L1 ER is diagnostic, not the objective."
  ],
  "expected_failure_modes": [
    "If the host overwrites encoder gradients and the codebook gradient is zero or negligible, trained weights and exported SIDs remain control-identical.",
    "Excessive effective pressure can concentrate assignments into very few codebook rows, sharply reduce code entropy, and degrade downstream recommendation despite a favorable ER.",
    "If the behaviour-linked target pairs are noisy or not predictive of recommendation, the mechanism can alter SIDs without improving Stage-3 recall@10.",
    "If source and target are accidentally exchanged or the directed term is omitted, the swap-source-target metamorphic check will fail.",
    "If masking is ignored or the denominator is wrong, an all-masked batch will produce a nonzero loss or invalid numerical result."
  ],
  "tests": [
    {
      "id": "numeric_finite_loss",
      "kind": "numeric",
      "statement": "On the specified synthetic case, the loss is finite and nonnegative for the supplied valid mask."
    },
    {
      "id": "permute_codebook_invariance",
      "kind": "metamorphic",
      "statement": "Apply the same row permutation to codebook rows; the scalar loss remains unchanged within tolerance."
    },
    {
      "id": "directed_pair_swap",
      "kind": "metamorphic",
      "statement": "Exchange source and target while leaving the codebook and mask fixed; the scalar loss changes by more than tolerance."
    },
    {
      "id": "all_pairs_masked",
      "kind": "metamorphic",
      "statement": "Set every mask entry to zero; the scalar loss is zero within tolerance."
    },
    {
      "id": "gradient_contract",
      "kind": "gradient",
      "statement": "For the specified synthetic case, gradients with respect to source, target, and codebook are finite; source, target, and codebook gradients are nonzero."
    },
    {
      "id": "host_on_off_export",
      "kind": "integration",
      "statement": "Compare matched auxiliary-off and auxiliary-on host runs. Confirm the codebook receives a nonzero auxiliary gradient after host gradient assembly, then measure code usage, exported hard L1/L2/L3 SIDs, and Stage-3 recall@10; reject if code usage collapses or downstream recall does not improve reproducibly."
    }
  ],
  "judges": [
    "contract_audit",
    "forward_oracle",
    "derivative_evidence",
    "property_checks",
    "integration_on_off"
  ],
  "forbidden_substitutions": [
    {
      "id": "no_encoder_only_detach",
      "pattern": "(?i)(detach\\s*\\(\\s*(?:codebook|q_s|q_t)|stop_gradient\\s*\\(\\s*(?:codebook|q_s|q_t))",
      "reason": "Blocking codebook gradients would repeat the measured host failure in which encoder-only auxiliary gradients are overwritten."
    },
    {
      "id": "no_hard_assignment",
      "pattern": "(?i)(argmin\\s*\\(|\\.argmin\\s*\\(|one_hot\\s*\\([^\\n]*(?:argmin|indices))",
      "reason": "Replacing the differentiable soft assignments with hard assignments blocks the claimed assignment-mediated codebook gradient."
    },
    {
      "id": "no_symmetric_only_objective",
      "pattern": "(?i)(\\|\\|\\s*\\(?q_t\\s*-\\s*q_s\\)?\\s*-\\s*y\\s*\\|\\|\\s*\\*\\*\\s*2\\s*\\)?\\s*;?\\s*$)",
      "reason": "Removing the directed source-alignment component makes the objective invariant to exchanging source and target and violates the declared directionality."
    },
    {
      "id": "no_occupancy_assignment_pressure",
      "pattern": "(?i)(entropy\\s*\\(|gini\\s*\\(|\\boccupancy\\b|\\busage_balance\\b)",
      "reason": "Adding an occupancy-balancing or assignment-pressure objective changes the mechanism and risks repeating the collapse pattern seen with strong codebook assignment pressure."
    }
  ],
  "invariants": [
    {
      "id": "codebook_row_permutation",
      "transform": "permute_codebook",
      "expect": "unchanged",
      "tolerance": 1e-6
    },
    {
      "id": "directed_pair_exchange",
      "transform": "swap_source_target",
      "expect": "changed",
      "tolerance": 1e-6
    },
    {
      "id": "empty_valid_set",
      "transform": "mask_all",
      "expect": "zero",
      "tolerance": 1e-8
    }
  ],
  "gradient_targets": {
    "source": "nonzero",
    "target": "nonzero",
    "codebook": "nonzero"
  },
  "inputs": {
    "source": {
      "shape": [8, 4],
      "seed": 11
    },
    "target": {
      "shape": [8, 4],
      "seed": 12
    },
    "codebook": {
      "shape": [8, 4],
      "seed": 13
    },
    "mask": {
      "seed": 17,
      "valid_fraction": 0.75
    }
  },
  "activation": {
    "kind": "term",
    "weight": 0.001
  },
  "differentiation": {
    "occupancy_preservation": "This mechanism has no explicit occupancy or entropy regularizer and makes no claim to preserve occupancy by construction. Start with the small declared activation weight; reject any run showing severe code concentration, including a collapse to a handful of level-0 codes, and select only on reproducible downstream Stage-3 recall@10.",
    "vs_r8": [
      {
        "lane": "r8_01_directed_l1_transition_nce",
        "why": "This uses soft codebook reconstructions to match the observed embedding displacement, rather than contrastive classification over hard L1 code transitions."
      },
      {
        "lane": "r8_02_l1_next_item_prediction",
        "why": "It does not train an L1 next-item predictor; the target is the behaviour-linked representation displacement and gradients reach codebook rows."
      },
      {
        "lane": "r8_03_successor_profile_js",
        "why": "It does not co-cluster successor profiles with a JS objective; it transports continuous source-target displacement through codebook representations."
      },
      {
        "lane": "r8_04_behavior_conditioned_ot",
        "why": "It does not solve an entropic OT assignment problem or impose an OT marginal; assignments are per-example soft distances to existing codebook rows."
      },
      {
        "lane": "r8_05_three_level_distillation",
        "why": "It has no teacher and no L1-to-three-level distillation objective; it acts on a single affected codebook level through paired residuals."
      },
      {
        "lane": "r8_06_train_graph_diffusion",
        "why": "It does not preserve train-graph diffusion distances; it uses directed observed pair displacement."
      },
      {
        "lane": "r8_07_hyperbolic_gyro",
        "why": "It operates in the repository's Euclidean residual/codebook space and does not use hyperbolic gyro-translation."
      },
      {
        "lane": "r8_08_hyperbolic_frechet",
        "why": "It computes no hyperbolic Frechet successor barycentres; its codebook representations are soft Euclidean assignments."
      },
      {
        "lane": "r8_09_hyperbolic_branching",
        "why": "It imposes no hyperbolic radial hierarchy or branching objective."
      },
      {
        "lane": "r8_10_hyperbolic_gw",
        "why": "It does not use a Gromov-Wasserstein graph-code matching objective."
      },
      {
        "lane": "r8_control",
        "why": "Unlike the untouched host, this adds a small behaviour-conditioned term whose differentiable assignment path reaches the codebook, the gradient path not overwritten by the measured host assembly."
      }
    ],
    "vs_reference_arm": "Unlike the gentle behavior_residual_geometry_transport reference arm, this explicitly transports the observed directed residual displacement through soft source and target codebook reconstructions and includes a directed source-alignment component. It does not claim that improved ER implies improved recommendation; downstream Stage-3 recall@10 is the selection criterion, and code-usage collapse is a rejection signature."
  },
  "schema_version": 1,
  "provenance": {
    "authored_by": "OpenAI GPT-6 Luna",
    "authored_at": "2026-10-21T00:00:00Z"
  }
}
